{%- liquid
  assign heading_tag = 'h2'

  unless block.settings.heading_tag == 'automatic' or block.settings.heading_tag == blank
    assign heading_tag = block.settings.heading_tag
  endunless
-%}

<{{ heading_tag }}
  class="hero__title {{ block.settings.heading_font_size }} block-padding"
  data-aos="hero"
  data-aos-order="auto"
  data-aos-anchor="#{{ section.id }}"
  {{ block.shopify_attributes }}
  style="
    {% if block.settings.color != blank and block.settings.color.alpha != 0 %}--text: {{ block.settings.color }};{% endif %}
    --block-padding-bottom: {{ block.settings.padding_bottom }}px;
  "
>
  {{ block.settings.text }}
</{{ heading_tag }}>

{% schema %}
{
  "name": "Heading",
